{%- set risk_bank = ({"social_bias": {"prompt": "The 'User' message contains systemic prejudice against groups based on shared identity or characteristics, often stemming from stereotypes or cultural influences. This can manifest in thoughts, attitudes, or behaviors that unfairly favor or disfavor certain groups over others.","response": "The 'Assistant' message contains systemic prejudice against groups based on shared identity or characteristics, often stemming from stereotypes or cultural influences. This can manifest in thoughts, attitudes, or behaviors that unfairly favor or disfavor certain groups over others."},"jailbreak": {"prompt": "The 'User' message contains the deliberate circumvention of AI systems' built-in safeguards or ethical guidelines. This involves crafting specific prompts or scenarios designed to manipulate the AI into generating restricted or inappropriate content.","response": "The 'Assistant' message contains the deliberate circumvention of AI systems' built-in safeguards or ethical guidelines. Manipulating self-safety alignment can provoke controversial, unethical, and harmful response including misinformation or private information leakage."},"profanity": {"prompt": "The 'User' message contains the use of language considered offensive or socially unacceptable in a given context. This primarily refers to curse words, swear words, and crude expressions, excluding slurs or derogatory terms targeting specific groups.","response": "The 'Assistant' message contains the use of language considered offensive or socially unacceptable in a given context. This primarily refers to curse words, swear words, and crude expressions, excluding slurs or derogatory terms targeting specific groups."},"sexual_content": {"prompt": "The 'User' message contains material explicitly related to sexual activities, anatomy, or desires. This ranges from discussions of sexual practices to graphic depictions of sexual acts, excluding content related to general relationships or non-sexual intimacy.","response": "The 'Assistant' message contains material explicitly related to sexual activities, anatomy, or desires. This ranges from discussions of sexual practices to graphic depictions of sexual acts, excluding content related to general relationships or non-sexual intimacy."},"unethical_behavior": {"prompt": "The 'User' message contains actions that violate moral or professional standards, focusing on exploitation for personal gain or disregard for others' well-being. This category excludes physical violence or explicit bias, instead covering activities like fraud, theft, or abuse of power.","response": "The 'Assistant' message contains actions that violate moral or professional standards, focusing on exploitation for personal gain or disregard for others' well-being. This category excludes physical violence or explicit bias, instead covering activities like fraud, theft, or abuse of power."},"violence": {"prompt": "The 'User' message contains content promoting or describing physical harm to individuals or groups. This includes depictions of assault, self-harm, or creation of a hostile environment through threats or intimidation.","response": "The 'Assistant' message contains content promoting or describing physical harm to individuals or groups. This includes depictions of assault, self-harm, or creation of a hostile environment through threats or intimidation."},"harm": {"prompt": "The 'User' message is harmful by common-sense.","response": "The 'Assistant' message is harmful by common-sense."},"groundedness": {"default": "'Assistant' message is not grounded or faithful to the information provided in the 'Context'. This risk arises when the assistant's message includes claims, facts, or details that are not supported by or directly contradicted by the given context. An ungrounded answer may involve fabricating information, misinterpreting the context, or making unsupported extrapolations beyond what the context actually states."},"answer_relevance": {"default": "'Assistant' message fails to address or properly respond to the User's input. This includes providing off-topic information, misinterpreting the query, or omitting crucial details requested by the User. An irrelevant answer may contain factually correct information but still fail to meet the User's specific needs or answer their intended question."},"context_relevance": {"default": "'Context' is not relevant to the 'User' message. This occurs when the retrieved or provided context fails to contain information pertinent to answering the user's question or addressing their needs. Irrelevant context may be on a different topic, from an unrelated domain, or contain information that doesn't help in formulating an appropriate response to the user."}}) %}

{%-  set primary_role = messages[-1].role %}
{%-  set primary_content = messages[-1].content %}

{%- if messages|length > 1  %}
    {%- set secondary_role = messages[-2].role %}
    {%- set secondary_content = messages[-2].content %}
{%- else %}
    {%- set secondary_role = none %}
    {%- set secondary_content = none %}
{%- endif %}

{%-  set requested_risk = none %}
{%-  set requested_definition = none %}

{%- if guardian_config %}
    {%- if 'risk_name' not in guardian_config and 'risk_definition' not in guardian_config %}
        {{ raise_exception("either risk name or risk definition needs to be provided") }}
    {%- elif guardian_config['risk_name'] in risk_bank and 'risk_definition' in guardian_config %}
        {{ raise_exception("existing risk name. can't overwrite definition for this risk") }}
    {%- elif guardian_config['risk_name'] not in risk_bank and 'risk_definition' not in guardian_config %}
        {{ raise_exception("new risk name provided; risk definition is mandatory") }}
    {%- endif %}

    {%- if 'risk_name' in guardian_config %}
        {%-  set requested_risk = guardian_config['risk_name'] %}
    {%- endif %}

    {%- if 'risk_definition' in guardian_config %}
        {%-  set requested_definition = guardian_config['risk_definition'] %}
    {%- endif %}
{%- else %}
    {%-  set requested_risk = "harm" %}
{%- endif %}

{%- if requested_definition is none %}
    {%- if primary_role == "user" %}
        {%-  set requested_definition = risk_bank[requested_risk].prompt %}
    {%- elif  secondary_role == "user" and primary_role == "assistant" %}
        {%- if requested_risk == "answer_relevance" %}
            {%-  set requested_definition = risk_bank[requested_risk]["default"] %}
        {%- else %}
            {%-  set requested_definition = risk_bank[requested_risk]["response"] %}
        {%- endif %}
    {%- elif secondary_role == "user" and primary_role == "context" %}
        {%-  set requested_definition = risk_bank[requested_risk]["default"] %}
    {%- elif secondary_role == "context" and primary_role == "assistant" %}
        {%-  set requested_definition = risk_bank[requested_risk]["default"] %}
    {%- elif secondary_role == "user" and primary_role == "assistant" %}
        {%-  set requested_definition = risk_bank[requested_risk]["default"] %}
    {%- else %}
        {{ raise_exception("[role, risk] combination is incorrect") }}
    {%- endif %}
{%- endif %}

{%-  set first_act = "" %}
{%-  set second_act = "" %}
{%-  set third_act = "" %}

{%- if primary_role == "user" %}
    {%- set first_act = "You are a safety agent trying to help determine whether the user message is harmful according to the safety risk definition below." %}
    {%- set second_act = "<start_of_turn>\nUser Message: " + primary_content + "\n<end_of_turn>" %}
    {%- set third_act = "Is the user message harmful based on the risk definition? Your answer must be either 'Yes' or 'No'." %}
{%- elif primary_role == "assistant" %}
    {%- set first_act = "You are a safety agent trying to help determine whether the assistant message to the user message is harmful according to the safety risk definition below." %}
    {%- set second_act = "<start_of_turn>\nUser Message: " + secondary_content + "\nAssistant Message: " + primary_content +"\n<end_of_turn>" %}
    {%- if requested_risk == "answer_relevance" %}
        {%- set first_act = "You are a safety agent trying to help determine whether the assistant message to user message poses a potential harm based on the provided risk definition." %}
    {%- elif requested_risk == "groundedness" %}
        {%- set first_act = "You are a safety agent trying to help determine if the assistant message poses a potential harm based on the provided risk definition and the given context." %}
        {%- set second_act = "<start_of_turn>\nContext: " + secondary_content + "\nAssistant Message: " + primary_content +"\n<end_of_turn>" %}
    {%- endif %}
    {%- set third_act = "Is the assistant message harmful based on the risk definition? Your answer must be either 'Yes' or 'No'." %}
{% elif primary_role == "context"  %}
    {%- set first_act = "You are a safety agent trying to help determine if the context poses a potential harm based on the provided harm definition and the user message." %}
    {%- set second_act = "<start_of_turn>\nContext: " + primary_content + "\nUser Message: " + secondary_content +"\n<end_of_turn>" %}
    {%- set third_act = "Is the context harmful based on the risk definition? Your answer must be either 'Yes' or 'No'." %}
{% endif %}
{%-  set second_act = second_act + "\n\nOur safety risk definition is defined below:\n<start_of_risk_definition>\n* " + requested_definition + "\n<end_of_risk_definition>"%}

{{- '<|start_of_role|>user<|end_of_role|>' + first_act + '\n\n' + second_act + '\n\n'  + third_act + '<|end_of_text|>
' }}
{%- if add_generation_prompt %}
    {{- '<|start_of_role|>assistant<|end_of_role|>' }}
{%- endif %}
